import { randomUUID } from 'crypto';

/**
 * Cart Item ID Value Object
 *
 * Represents a unique identifier for a CartItem entity.
 *
 * Pattern: cuid() generated by Prisma
 */
export class CartItemId {
  private readonly _value: string;

  private constructor(value: string) {
    if (!value || value.trim().length === 0) {
      throw new Error('CartItemId cannot be empty');
    }
    this._value = value;
  }

  /**
   * Generate new CartItemId (for creation)
   */
  static generate(): CartItemId {
    return new CartItemId(randomUUID());
  }

  /**
   * Create from existing string (from database)
   */
  static fromString(value: string): CartItemId {
    return new CartItemId(value);
  }

  get value(): string {
    return this._value;
  }

  equals(other: CartItemId): boolean {
    if (!(other instanceof CartItemId)) {
      return false;
    }
    return this._value === other._value;
  }

  toString(): string {
    return this._value;
  }
}
